        .footer-bottom p {
            font-size: 14px;
            color: var(--text-secondary);
        }

        .footer-social {
            display: flex;
            gap: 16px;
        }

        .social-link {
            width: 40px;
            height: 40px;
            border-radius: 50%;
            background-color: var(--bg-tertiary);
            display: flex;
            align-items: center;
            justify-content: center;
            color: var(--text-primary);
            text-decoration: none;
            transition: background-color 0.3s ease;
            border-radius: 4px;
        }

        .social-link:hover {
            background-color: var(--accent-primary);
        }

        .social-link:focus {
            outline: 2px solid var(--accent-primary);
            outline-offset: 2px;
        }

        /* Responsive Design */
        @media (max-width: 768px) {
            .header-container {
                height: 64px;
            }

            .logo {
                font-size: 20px;
            }

            nav ul {
                display: none;
                position: absolute;
                top: 64px;
                left: 0;
                right: 0;
                flex-direction: column;
                gap: 0;
                background-color: var(--bg-secondary);
                border-bottom: 1px solid var(--border-color);
                padding: 16px;
            }

            nav ul.open {
                display: flex;
            }

            nav a {
                padding: 12px 8px;
            }

            .nav-toggle {
                display: block;
            }

            .hero {
                padding: 48px 24px;
            }

            .hero h1 {
                font-size: 36px;
            }

            .hero p {
                font-size: 16px;
            }

            .section-header h2 {
                font-size: 28px;
            }

            .hero::before {
                width: 300px;
                height: 300px;
                top: -25%;
            }

            .products-grid {
                grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
                gap: 20px;
            }

            .deals-grid {
                grid-template-columns: 1fr;
            }

            .editorial-grid {
                grid-template-columns: 1fr;
            }

            .newsletter {
                padding: 40px 24px;
            }

            .newsletter h2 {
                font-size: 24px;
            }

            .newsletter-form {
                flex-direction: column;
            }

            .newsletter-form input,
            .newsletter-form button {
                width: 100%;
            }

            .footer-content {
                grid-template-columns: 1fr 1fr;
                gap: 24px;
            }

            .footer-bottom {
                flex-direction: column;
                justify-content: center;
                text-align: center;
            }
        }

        @media (max-width: 480px) {
            .hero h1 {
                font-size: 28px;
            }

            .section-header h2 {
                font-size: 22px;
            }

            .cta-button {
                padding: 12px 32px;
                font-size: 14px;
            }

            .products-grid {
                grid-template-columns: 1fr;
            }

            .footer-content {
                grid-template-columns: 1fr;
            }
        }

        /* Accessibility: Reduced motion */
        @media (prefers-reduced-motion: reduce) {
            * {
                animation-duration: 0.01ms !important;
                animation-iteration-count: 1 !important;
                transition-duration: 0.01ms !important;
            }
        }
    </style>
</head>
