            opacity: 0;
            z-index: -1;
            transition: opacity 0.3s ease;
        }

        .deal-card:hover::before {
            opacity: 0.2;
        }

        .deal-badge {
            display: inline-block;
            background-color: var(--accent-secondary);
            color: white;
            padding: 6px 12px;
            border-radius: 20px;
            font-size: 12px;
            font-weight: 700;
            margin-bottom: 12px;
            text-transform: uppercase;
            letter-spacing: 0.5px;
