        .deal-title {
            font-size: 24px;
            font-weight: 700;
            margin-bottom: 12px;
        }

        .deal-description {
            font-size: 14px;
            color: var(--text-secondary);
            margin-bottom: 20px;
        }

        .deal-cta {
            color: var(--accent-primary);
            text-decoration: none;
            font-weight: 600;
            font-size: 14px;
            display: inline-flex;
            align-items: center;
