        .deal-cta:focus {
            outline: 2px solid var(--accent-primary);
            outline-offset: 2px;
        }

        /* Editorial Section */
        .editorial {
            margin: 80px 0;
        }

        .editorial-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
            gap: 28px;
        }

        .editorial-card {
