            text-transform: uppercase;
            margin-bottom: 8px;
            letter-spacing: 0.5px;
        }

        .editorial-title {
            font-size: 20px;
            font-weight: 700;
            margin-bottom: 12px;
            line-height: 1.3;
        }

        .editorial-excerpt {
            font-size: 14px;
            color: var(--text-secondary);
            margin-bottom: 16px;
            flex-grow: 1;
            line-height: 1.5;
