            font-weight: 600;
            font-size: 14px;
            display: inline-flex;
            align-items: center;
            gap: 6px;
            transition: gap 0.3s ease;
            border-radius: 4px;
            padding: 4px 8px;
            width: fit-content;
        }

        .editorial-link:hover,
        .editorial-link:focus {
            gap: 10px;
        }

        .editorial-link:focus {
            outline: 2px solid var(--accent-primary);
            outline-offset: 2px;
        }

        /* Newsletter Section */
        .newsletter {
            background: linear-gradient(135deg, rgba(99, 102, 241, 0.1), rgba(236, 72, 153, 0.1));
            border: 1px solid var(--border-color);
            border-radius: 16px;
            padding: 60px 40px;
            margin: 80px 0;
            text-align: center;
        }

        .newsletter h2 {
            font-size: 32px;
            font-weight: 700;
            margin-bottom: 12px;
        }

        .newsletter p {
            font-size: 16px;
            color: var(--text-secondary);
            margin-bottom: 28px;
        }

        .newsletter-form {
            display: flex;
            gap: 12px;
            max-width: 500px;
            margin: 0 auto;
            flex-wrap: wrap;
            justify-content: center;
